// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetCoreHealth Read Core deployment health
	// (GET /healthz)
	GetCoreHealth(ctx context.Context, request GetCoreHealthRequestObject) (GetCoreHealthResponseObject, error)
	// CreateAttempt Create a draft Attempt against an assigned PracticeActivity
	// (POST /v1/attempts)
	CreateAttempt(ctx context.Context, request CreateAttemptRequestObject) (CreateAttemptResponseObject, error)
	// GetAttempt Read one learner-owned Attempt
	// (GET /v1/attempts/{attempt_id})
	GetAttempt(ctx context.Context, request GetAttemptRequestObject) (GetAttemptResponseObject, error)
	// PatchAttempt Replace mutable draft response state on an Attempt
	// (PATCH /v1/attempts/{attempt_id})
	PatchAttempt(ctx context.Context, request PatchAttemptRequestObject) (PatchAttemptResponseObject, error)
	// SubmitAttempt Submit an Attempt exactly once as one logical operation
	// (POST /v1/attempts/{attempt_id}/submissions)
	SubmitAttempt(ctx context.Context, request SubmitAttemptRequestObject) (SubmitAttemptResponseObject, error)
	// GetDailyPlan Read the current DailyPlan snapshot
	// (GET /v1/daily-plan)
	GetDailyPlan(ctx context.Context, request GetDailyPlanRequestObject) (GetDailyPlanResponseObject, error)
	// GetEvaluation Read one learner-safe Evaluation projection
	// (GET /v1/evaluations/{evaluation_id})
	GetEvaluation(ctx context.Context, request GetEvaluationRequestObject) (GetEvaluationResponseObject, error)
	// StreamResourceEvents Stream access-scoped non-authoritative resource update hints
	// (GET /v1/event-stream)
	StreamResourceEvents(ctx context.Context, request StreamResourceEventsRequestObject) (StreamResourceEventsResponseObject, error)
	// ListGaps List learner GapEvaluation and ActionIntent results
	// (GET /v1/gaps)
	ListGaps(ctx context.Context, request ListGapsRequestObject) (ListGapsResponseObject, error)
	// GetMe Read the authenticated Core actor projection
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// CreatePracticeActivity Resolve and assign one current eligible PracticeActivity
	// (POST /v1/practice-activities)
	CreatePracticeActivity(ctx context.Context, request CreatePracticeActivityRequestObject) (CreatePracticeActivityResponseObject, error)
	// GetPracticeActivity Read one learner-owned PracticeActivity projection
	// (GET /v1/practice-activities/{practice_activity_id})
	GetPracticeActivity(ctx context.Context, request GetPracticeActivityRequestObject) (GetPracticeActivityResponseObject, error)
	// ListPracticeModes List the stable learner-facing practice-mode catalog
	// (GET /v1/practice-modes)
	ListPracticeModes(ctx context.Context, request ListPracticeModesRequestObject) (ListPracticeModesResponseObject, error)
	// GetProgress Read target-relative learner progress and current claim state
	// (GET /v1/progress)
	GetProgress(ctx context.Context, request GetProgressRequestObject) (GetProgressResponseObject, error)
	// GetReviewQueue Read due review work while preserving semantic queue kind
	// (GET /v1/review-queue)
	GetReviewQueue(ctx context.Context, request GetReviewQueueRequestObject) (GetReviewQueueResponseObject, error)
	// GetTargetProfile Read the current TargetProfile
	// (GET /v1/target-profile)
	GetTargetProfile(ctx context.Context, request GetTargetProfileRequestObject) (GetTargetProfileResponseObject, error)
	// PutTargetProfile Replace the current TargetProfile
	// (PUT /v1/target-profile)
	PutTargetProfile(ctx context.Context, request PutTargetProfileRequestObject) (PutTargetProfileResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetCoreHealth operation middleware
func (sh *strictHandler) GetCoreHealth(w http.ResponseWriter, r *http.Request) {
	var request GetCoreHealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetCoreHealth(ctx, request.(GetCoreHealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetCoreHealth")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetCoreHealthResponseObject); ok {
		if err := validResponse.VisitGetCoreHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

